    const quality = (t) => Math.max(0, 1 - Math.abs(j.at[t] - 1) / 0.45);
    const ability = (p) => (p.r.blk * 0.5 + p.r.reb * 0.3 + p.r.spd * 0.2) / 100 + (p.size - 1) * 0.4;
    const score = (t) => quality(t) * 0.65 + ability(j.jumpers[t]) * 0.35 + this.rng() * 0.06;
    const win = score(0) >= score(1) ? 0 : 1;
