async function unpack(s) {
  if (!s.startsWith("gz1:")) throw new Error("unknown evidence format");
  const bytes = Uint8Array.from(atob(s.slice(4)), (c) => c.charCodeAt(0));
  const text = await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
  return JSON.parse(text);
}

// src/franchise/league.ts
var USER_STYLE = { color: "#3b6fd8", color2: "#16224a" };
function contrastAway(home, away) {
  if (colorDistance(home.color, away.color) >= 110) return away;
  return { ...away, color: colorDistance(home.color, "#e3350d") < 110 ? "#f4f1e8" : "#e3350d" };
}
function colorDistance(a, b) {
  const rgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
  const [x, y] = [rgb(a), rgb(b)];
  return Math.hypot(x[0] - y[0], x[1] - y[1], x[2] - y[2]);
}

// src/util.ts
var abbr = (name) => (name.replace(/[^a-z0-9]/gi, "").slice(0, 3) || "YOU").toUpperCase();

// src/multiplayer/shared/roster.ts
function randomFive(rng = Math.random, pool = POKEMON) {
  return POSITIONS.map((p) => {
    const at = pool.filter((m) => m.pos === p);
    return at[Math.floor(rng() * at.length)];
  });
}
var RANKED_EXCLUDED = [
  150,
  // Mewtwo, SF 97
  249,
  // Lugia, C 96
  250,
  // Ho-Oh, C 95
  151,
  // Mew, PG 94
  384,
  // Rayquaza, PF 93
  381,
  // Latios, SF 92
  383,
  // Groudon, PF 92
  382,
  // Kyogre, C 92
  380
  // Latias, SF 91
];
var RANKED_MAX_GAP = 3;
var RANKED_MAX_SPREAD = 25;
var RANKED_TRIES = 400;
var SPREAD_TRIES = 200;
var RANKED_POOL = POKEMON.filter((m) => !RANKED_EXCLUDED.includes(m.dex));
var teamOvr = (team) => team.reduce((s, m) => s + m.ovr, 0);
var teamSpread = (team) => Math.max(...team.map((m) => m.ovr)) - Math.min(...team.map((m) => m.ovr));
function evenFive(rng) {
  let best = randomFive(rng, RANKED_POOL);
  for (let i = 1; i < SPREAD_TRIES && teamSpread(best) > RANKED_MAX_SPREAD; i++) {
    const t = randomFive(rng, RANKED_POOL);
    if (teamSpread(t) < teamSpread(best)) best = t;
  }
  return best;
}
function balancedRosters(rng) {
  let best = null;
  let bestGap = Infinity;
  for (let i = 0; i < RANKED_TRIES && bestGap > RANKED_MAX_GAP; i++) {
    const a2 = evenFive(rng);
    const b2 = evenFive(rng);
    const gap = Math.abs(teamOvr(a2) - teamOvr(b2));
    if (gap < bestGap) {
      best = [a2, b2];
      bestGap = gap;
    }
  }
  const [a, b] = best;
  return rng() < 0.5 ? [a, b] : [b, a];
}
function rostersFor(seed, queue = "social") {
  const rng = seededRng((seed ^ 1540483477) >>> 0);
  return queue === "social" ? [randomFive(rng), randomFive(rng)] : balancedRosters(rng);
}

// src/multiplayer/shared/rtc.ts
var MAX_BYTES = 64 * 1024;

// src/multiplayer/shared/netplay.ts
function setupFor(match, quarterLen = match.game.quarterLen) {
  const drafted = match.game.rosters;
  const [homeMons, awayMons] = drafted ? [drafted[0].map(monByDex), drafted[1].map(monByDex)] : rostersFor(match.game.seed, match.queue);
  const names = match.side === 0 ? [match.me.name, match.opponent.name] : [match.opponent.name, match.me.name];
  const home = { name: names[0], abbr: abbr(names[0]), ...USER_STYLE, human: true, roster: homeMons };
  const away = contrastAway(home, { name: names[1], abbr: abbr(names[1]), ...USER_STYLE, color: "#7a3fd8", color2: "#24124a", human: true, roster: awayMons });
  const team = (t) => ({ name: t.name, abbr: t.abbr, color: t.color, color2: t.color2, roster: t.roster.map((m) => m.dex) });
  return { matchId: match.id, engineVersion: ENGINE_VERSION, seed: match.game.seed, quarterLen, home: team(home), away: team(away) };
}

// src/multiplayer/shared/judgeMatch.ts
function hostView(b) {
  return {
    id: b.match_id,
    queue: "pack",
    side: 0,
    me: { id: b.host, name: b.host_name },
    opponent: { id: b.guest, name: b.guest_name, mmr: 1e3, simulated: false },
    game: { seed: Number(b.seed) >>> 0, quarterLen: b.quarter_len, rosters: null },
    keys: [b.host_key, b.guest_key]
  };
}
var side = (s) => s === 0 ? "host" : "guest";
var NAMES = ["host", "guest"];
async function judgeBattle(b) {
  if (!b.host_key || !b.guest_key) return { result: "void", outcome: "no-game", note: "The game never started (no keys registered)." };
  if (!b.uploads.length) return { result: "void", outcome: "no-game", note: "Neither player uploaded anything: the game never got going." };
  const inputs = [];
  const resigns = [];
  const notes = [];
  for (const u of b.uploads) {
    try {
      const e = await unpack(u);
      inputs.push(...e.inputs ?? []);
      resigns.push(...Array.isArray(e.resigns) ? e.resigns : []);
    } catch (e) {
      notes.push(`an upload could not be read (${e.message})`);
    }
  }
  if (!inputs.length) {
    return notes.length ? { result: "review", outcome: "no-evidence", note: ["Nothing signed to judge.", ...notes].join(" ") } : { result: "void", outcome: "no-game", note: "Nobody signed a single input: the game never got going." };
  }
  const v = await judge({ setup: setupFor(hostView(b)), keys: [b.host_key, b.guest_key], inputs, applied: [], lockstep: { emptyTicks: MIN_DELAY }, resigns });
  const note = (...extra) => [...extra, `${v.score[0]}-${v.score[1]} after ${v.ticks} ticks.`, ...notes, ...v.notes].join(" ");
  if (v.status === "final") {
    return v.winner === null ? { result: "void", outcome: "tie", note: note(), verdict: v } : { result: side(v.winner), outcome: "final", note: note(), verdict: v };
  }
  if (v.status === "forfeit" && v.winner !== null) return { result: side(v.winner), outcome: "forfeit", note: note(), verdict: v };
  if (v.status === "incomplete") {
    if (v.ticks <= MIN_DELAY) return { result: "void", outcome: "no-game", note: note("Not one tick was played with both players' inputs."), verdict: v };
    if (v.ticks >= MAX_TICKS) return { result: "review", outcome: "hard-stop", note: note(), verdict: v };
    if (v.resigned !== void 0) {
      const q2 = v.resigned;
      return { result: side(1 - q2), outcome: "resigned", note: note(`${NAMES[q2]} (${q2 ? b.guest_name : b.host_name}) left the game and forfeits.`), verdict: v };
    }
    if (b.host_uploaded !== b.guest_uploaded) {
      const q2 = b.host_uploaded ? 1 : 0;
      return { result: side(1 - q2), outcome: "abandoned", note: note(`${NAMES[q2]} (${q2 ? b.guest_name : b.host_name}) went quiet and never uploaded, so forfeits.`), verdict: v };
    }
    return { result: "review", outcome: "disconnect", note: note("Both players stayed and uploaded: a person checks both connection logs."), verdict: v };
  }
  return { result: "review", outcome: v.status, note: note(), verdict: v };
}
export {
  judgeBattle
};
